<template>
  <div class="space-y-6">
    <PageHeader title="用户订阅" parent="用户" description="订阅关联一台设备，使用其独立凭据，按授权节点组与已发布配置生成。"><template #actions><button @click="openRotate" class="ios-btn-primary">生成 / 重置订阅</button></template></PageHeader>
    <ErrorState v-if="error" :message="error" @retry="load" /><LoadingSkeleton v-else-if="loading" /><EmptyState v-else-if="!tokens.length" title="暂无有效订阅" />
    <DataTable v-else><template #header><th>用户</th><th>设备</th><th>创建时间</th><th>最后更新</th><th>操作</th></template><template #body><tr v-for="token in tokens" :key="token.id"><td class="p-4 font-semibold text-[15px] text-ios-label">{{ users.find(user => user.id === token.userId)?.username || token.userId }}</td><td class="text-xs text-ios-secondary">{{ allDevices.find(device => device.id === token.deviceId)?.name || token.deviceId }}</td><td class="text-xs font-mono tabular-nums text-ios-tertiary">{{ formatTime(token.createdAt) }}</td><td class="text-xs font-mono tabular-nums text-ios-tertiary">{{ formatTime(token.lastFetchedAt) }}</td><td class="space-x-2"><button @click="preview(token)" class="ios-action-btn-primary">包含节点</button><button @click="revokeTarget = token; confirmVisible = true" class="ios-action-btn-danger">撤销</button></td></tr></template><template #footer><Pagination :total="total" :current-page="page" :page-size="20" @update:page="changePage" /></template></DataTable>
    <FormDrawer v-model="drawer" title="生成用户订阅" description="重新生成后该用户的旧 Token 立即失效。请选择使用此订阅的设备。" :loading="saving" @confirm="rotate" confirm-text="确认生成并撤销旧 Token"><div class="space-y-4 text-sm"><label class="block text-xs font-medium text-ios-secondary">用户<select v-model="selectedUser" @change="loadDevices" class="form-input-base mt-1.5"><option value="">请选择</option><option v-for="user in users" :key="user.id" :value="user.id">{{ user.username }}</option></select></label><label class="block text-xs font-medium text-ios-secondary">设备<select v-model="selectedDevice" class="form-input-base mt-1.5"><option value="">请选择</option><option v-for="device in devices.filter(item => item.status === 'active')" :key="device.id" :value="device.id">{{ device.name }}</option></select></label><p class="text-xs text-ios-tertiary">没有设备时，请先在设备页面创建独立凭据。节点接入配置发布成功后才会进入订阅。</p></div></FormDrawer>
    <AppDialog v-model="urlDialog" title="订阅地址" description="明文 Token 仅展示一次，请复制保存。" :show-footer="false"><div class="space-y-4"><CodePreview :code="url" /><CodePreview :code="url ? url + '?format=base64' : ''" title="Base64 URI 列表" /><CodePreview :code="url ? url + '?format=sing-box' : ''" title="sing-box JSON" /></div></AppDialog>
    <AppDialog v-model="previewDialog" title="订阅可用入口" :show-footer="false"><p v-if="!endpoints.length" class="text-sm text-ios-tertiary">当前没有符合授权、设备凭据与成功发布配置的入口。请检查节点组、订阅可见性和配置发布状态。</p><div v-for="endpoint in endpoints" :key="endpoint.nodeId + endpoint.inboundId" class="py-3 border-b border-black/[0.06] last:border-0"><p class="font-semibold text-ios-label">{{ endpoint.nodeName }}</p><p class="text-xs text-ios-secondary mt-1">{{ endpoint.protocol }} · {{ endpoint.address }}:{{ endpoint.port }}</p></div></AppDialog>
    <ConfirmDialog v-model="confirmVisible" title="撤销订阅" message="撤销后，当前 Token 不能再用于更新订阅。节点上的既有凭据需通过配置发布单独撤销。" @confirm="revoke" />
  </div>
</template>
<script setup lang="ts">
import { ref, onMounted, watch } from 'vue'; import { userAPI, type ProxyUser, type ProxyDevice, type TokenView } from '../api'; import { formatTime } from '../../../app/auth'; import { showToast } from '../../../app/api'; import PageHeader from '../../../components/PageHeader.vue'; import DataTable from '../../../components/DataTable.vue'; import Pagination from '../../../components/Pagination.vue'; import FormDrawer from '../../../components/FormDrawer.vue'; import AppDialog from '../../../components/AppDialog.vue'; import CodePreview from '../../../components/CodePreview.vue'; import ConfirmDialog from '../../../components/ConfirmDialog.vue'; import ErrorState from '../../../components/ErrorState.vue'; import EmptyState from '../../../components/EmptyState.vue'; import LoadingSkeleton from '../../../components/LoadingSkeleton.vue';
const tokens = ref<TokenView[]>([]); const users = ref<ProxyUser[]>([]); const allDevices = ref<ProxyDevice[]>([]); const devices = ref<ProxyDevice[]>([]); const total = ref(0); const page = ref(1); const error = ref(''); const loading = ref(false); const drawer = ref(false); const saving = ref(false); const selectedUser = ref(''); const selectedDevice = ref(''); const urlDialog = ref(false); const url = ref(''); const previewDialog = ref(false); const endpoints = ref<{ nodeId: string; nodeName: string; inboundId: string; protocol: string; address: string; port: number }[]>([]); const revokeTarget = ref<TokenView | null>(null); const confirmVisible = ref(false);
async function load() { loading.value = true; try { const [result, u, d] = await Promise.all([userAPI.tokens(page.value), userAPI.list(1, '', 100), userAPI.devices('', 1, 100)]); tokens.value = result.items; total.value = result.total; users.value = u.items; allDevices.value = d.items; error.value = ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } }
function changePage(value: number) { page.value = value; load(); } function openRotate() { selectedUser.value = ''; selectedDevice.value = ''; devices.value = []; drawer.value = true; }
async function loadDevices() { selectedDevice.value = ''; try { devices.value = selectedUser.value ? (await userAPI.devices(selectedUser.value, 1, 100)).items : []; } catch (e) { showToast((e as Error).message, 'error'); } }
async function rotate() { if (saving.value) return; if (!selectedUser.value || !selectedDevice.value) { showToast('请选择用户和设备', 'error'); return; } saving.value = true; try { const result = await userAPI.rotateToken(selectedUser.value, selectedDevice.value); drawer.value = false; url.value = new URL(result.path, location.origin).href; urlDialog.value = true; await load(); } catch (e) { showToast((e as Error).message, 'error'); } finally { saving.value = false; } }
async function preview(token: TokenView) { try { endpoints.value = (await userAPI.preview(token.userId, token.deviceId)).items; previewDialog.value = true; } catch (e) { showToast((e as Error).message, 'error'); } }
async function revoke() { if (!revokeTarget.value) return; try { await userAPI.revokeToken(revokeTarget.value.userId); showToast('订阅已撤销'); await load(); } catch (e) { showToast((e as Error).message, 'error'); } }
watch(urlDialog, visible => { if (!visible) url.value = ''; }); onMounted(load);
</script>
